// Everything that depends on how TikTok's website is built lives in this file,
// so when TikTok changes its site there is one place to fix. Structure observed
// on tiktok.com on 2026-10-12.

export interface CaptionTrack {
  url: string;
  language: string;
  format: string;
  autoGenerated: boolean;
  original: boolean;
}

export interface TikTokVideo {
  id: string;
  author: string;
  description: string;
  hashtags: string[];
  onScreenText: string[];
  captionTracks: CaptionTrack[];
  noCaptionReason: number | null;
  aiLabel: { labeled: boolean; description: string };
}

/** The script element where TikTok embeds each page's initial data. */
export const EMBEDDED_DATA_ELEMENT_ID = "__UNIVERSAL_DATA_FOR_REHYDRATION__";

// Keep in sync with host_permissions in extension/manifest.json.
const CAPTION_DOMAINS = ["tiktok.com", "tiktokcdn.com", "tiktokcdn-us.com"];

type Json = Record<string, unknown>;

const asObject = (value: unknown): Json | undefined =>
  typeof value === "object" && value !== null && !Array.isArray(value)
    ? (value as Json)
    : undefined;
const asArray = (value: unknown): unknown[] =>
  Array.isArray(value) ? value : [];
const asString = (value: unknown): string =>
  typeof value === "string" ? value : "";

/** Pulls every video record out of a TikTok API response or embedded page data. */
export function extractVideos(json: unknown): TikTokVideo[] {
  const root = asObject(json);
  if (!root) return [];
  const pageScope = asObject(root.__DEFAULT_SCOPE__);
  const candidates = pageScope
    ? [asObject(asObject(pageScope["webapp.video-detail"])?.itemInfo)?.itemStruct]
    : [...asArray(root.itemList), asObject(root.itemInfo)?.itemStruct];
  return candidates.flatMap((candidate) => {
    const video = toVideo(candidate);
    return video ? [video] : [];
  });
}

function toVideo(value: unknown): TikTokVideo | null {
  const item = asObject(value);
  const video = asObject(item?.video);
  const id = asString(item?.id);
  if (!item || !video || !/^\d+$/.test(id)) return null;

  const captionInfo = asObject(video.claInfo);
  const tracks = [
    ...asArray(captionInfo?.captionInfos),
    ...asArray(video.subtitleInfos),
  ].flatMap((entry) => {
    const track = toCaptionTrack(entry);
    return track ? [track] : [];
  });
  const reason = captionInfo?.noCaptionReason;
  const aiDescription = asString(item.AIGCDescription);

  return {
    id,
    author: asString(asObject(item.author)?.uniqueId),
    description: asString(item.desc),
    hashtags: asArray(item.textExtra)
      .map((tag) => asString(asObject(tag)?.hashtagName))
      .filter(Boolean),
    onScreenText: asArray(item.stickersOnItem)
      .flatMap((sticker) => asArray(asObject(sticker)?.stickerText).map(asString))
      .filter(Boolean),
    captionTracks: tracks.filter(
      (track, index) =>
        tracks.findIndex((other) => other.url === track.url) === index,
    ),
    noCaptionReason: typeof reason === "number" ? reason : null,
    aiLabel: {
      labeled: item.IsAigc === true || aiDescription !== "",
      description: aiDescription,
    },
  };
}

// TikTok lists captions in two places with different field names:
// video.claInfo.captionInfos (camelCase) and video.subtitleInfos (PascalCase).
// The entry field names come from TikTok pages seen before 2026; only empty
// caption lists could be inspected on 2026-10-12, so confirm them on a live video.
function toCaptionTrack(value: unknown): CaptionTrack | null {
  const entry = asObject(value);
  if (!entry) return null;
  const url =
    asString(entry.url) ||
    asString(entry.Url) ||
    asString(asArray(entry.urlList)[0]) ||
    asString(asArray(entry.UrlList)[0]);
  if (!url) return null;
  return {
    url,
    language: asString(entry.language) || asString(entry.LanguageCodeName),
    format: (
      asString(entry.captionFormat) || asString(entry.Format)
    ).toLowerCase(),
    autoGenerated: entry.isAutoGen === true || entry.Source === "ASR",
    original: entry.isOriginalCaption === true || entry.Source === "ASR",
  };
}

/** Prefers captions in the speaker's own language, then English, then any. */
export function pickCaptionTrack(tracks: CaptionTrack[]): CaptionTrack | null {
  const readable = tracks.filter(
    (track) => track.format === "" || track.format === "webvtt",
  );
  return (
    readable.find((track) => track.original) ??
    readable.find((track) => /^en/i.test(track.language)) ??
    readable[0] ??
    null
  );
}

/**
 * Finds which TikTok video a player belongs to. TikTok wraps each player in an
 * element whose id ends with the video's id (`xgwrapper-0-7621991999251467550`);
 * on a single video's page the id is also in the address (`/@user/video/7621…`).
 */
export function videoIdFrom(
  ancestorIds: string[],
  pathname: string,
): string | null {
  for (const id of ancestorIds) {
    const match = /^xgwrapper-\d+-(\d+)$/.exec(id);
    if (match) return match[1];
  }
  return /\/video\/(\d+)/.exec(pathname)?.[1] ?? null;
}

/** Whether a network response might carry video records worth reading. */
export function isTikTokApiUrl(url: string): boolean {
  const parsed = parseHttpsUrl(url);
  return (
    parsed !== null &&
    isOnDomain(parsed.hostname, "tiktok.com") &&
    parsed.pathname.startsWith("/api/")
  );
}

/** Whether a caption file address points at TikTok's own servers. */
export function isTikTokCaptionUrl(url: string): boolean {
  const parsed = parseHttpsUrl(url);
  return (
    parsed !== null &&
    CAPTION_DOMAINS.some((domain) => isOnDomain(parsed.hostname, domain))
  );
}

function parseHttpsUrl(url: string): URL | null {
  try {
    const parsed = new URL(url);
    return parsed.protocol === "https:" ? parsed : null;
  } catch {
    return null;
  }
}

const isOnDomain = (hostname: string, domain: string): boolean =>
  hostname === domain || hostname.endsWith(`.${domain}`);

// Reads WebVTT, the caption file format TikTok serves.

export interface Cue {
  /** Seconds from the start of the video. */
  start: number;
  text: string;
}

const ENTITIES: Record<string, string> = {
  amp: "&",
  lt: "<",
  gt: ">",
  quot: '"',
  "#39": "'",
  nbsp: " ",
};

export function parseWebVtt(vtt: string): Cue[] {
  const cues: Cue[] = [];
  for (const block of vtt.replace(/\r\n?/g, "\n").split(/\n{2,}/)) {
    const lines = block.split("\n");
    const timingLine = lines.findIndex((line) => line.includes("-->"));
    // Blocks without a timing line are the header, NOTE, or STYLE blocks.
    if (timingLine === -1) continue;
    const text = lines
      .slice(timingLine + 1)
      .join(" ")
      .replace(/<[^>]*>/g, "")
      .replace(/&(amp|lt|gt|quot|#39|nbsp);/g, (_, name: string) => ENTITIES[name])
      .replace(/\s+/g, " ")
      .trim();
    // Skip empty cues and repeats of the cue before (captions that linger).
    if (!text || text === cues.at(-1)?.text) continue;
    cues.push({ start: parseTimestamp(lines[timingLine]), text });
  }
  return cues;
}

function parseTimestamp(timingLine: string): number {
  const match = /(?:(\d+):)?(\d{1,2}):(\d{2})\.(\d{3})/.exec(timingLine);
  if (!match) return 0;
  const [, hours = "0", minutes, seconds, milliseconds] = match;
  return (
    Number(hours) * 3600 +
    Number(minutes) * 60 +
    Number(seconds) +
    Number(milliseconds) / 1000
  );
}

// Messages passed between the extension's scripts.
import type { TikTokVideo } from "./tiktok.ts";

/** Tags messages from page-hook.ts so content.ts ignores anything else posted on the page. */
export const PAGE_HOOK_SOURCE = "video-fact-check:page-hook";

export interface PageHookMessage {
  source: typeof PAGE_HOOK_SOURCE;
  videos: TikTokVideo[];
}

export interface FetchCaptionRequest {
  type: "fetchCaption";
  url: string;
}

export type FetchCaptionResponse =
  | { ok: true; text: string }
  | { ok: false; error: string };

// Runs inside the TikTok page itself (not the extension's isolated world) so it
// can see the video data TikTok's own code downloads. It never changes what
// TikTok receives: it reads a copy of each response and hands it to content.ts.
import { PAGE_HOOK_SOURCE, type PageHookMessage } from "./messages.ts";
import { extractVideos, isTikTokApiUrl } from "./tiktok.ts";

function forward(json: unknown): void {
  const videos = extractVideos(json);
  if (videos.length === 0) return;
  const message: PageHookMessage = { source: PAGE_HOOK_SOURCE, videos };
  window.postMessage(message, window.location.origin);
}

const originalFetch = window.fetch;
window.fetch = async (...args: Parameters<typeof fetch>) => {
  const response = await originalFetch.apply(window, args);
  if (isTikTokApiUrl(response.url)) {
    // Responses that aren't JSON have nothing for us, so a parse failure is ignored.
    response
      .clone()
      .json()
      .then(forward, () => {});
  }
  return response;
};

const originalOpen = XMLHttpRequest.prototype.open;
XMLHttpRequest.prototype.open = function (
  this: XMLHttpRequest,
  ...args: unknown[]
) {
  this.addEventListener("load", () => {
    if (isTikTokApiUrl(this.responseURL)) forward(readJson(this));
  });
  Reflect.apply(originalOpen, this, args);
} as typeof XMLHttpRequest.prototype.open;

function readJson(request: XMLHttpRequest): unknown {
  if (request.responseType === "json") return request.response;
  if (request.responseType !== "" && request.responseType !== "text") {
    return null;
  }
  try {
    return JSON.parse(request.responseText);
  } catch {
    return null;
  }
}

// Runs in the extension's isolated world on tiktok.com. Collects video records
// from the page, notices which video starts playing, and (for milestone 1)
// prints its transcript and AI label to the browser console.
import {
  PAGE_HOOK_SOURCE,
  type FetchCaptionRequest,
  type FetchCaptionResponse,
} from "./messages.ts";
import {
  EMBEDDED_DATA_ELEMENT_ID,
  extractVideos,
  pickCaptionTrack,
  videoIdFrom,
  type TikTokVideo,
} from "./tiktok.ts";
import { parseWebVtt } from "./webvtt.ts";

const LOG_PREFIX = "[Fact check]";
const DATA_WAIT_MS = 5000;

const videosById = new Map<string, TikTokVideo>();
const reported = new Set<string>();
let waitingForId: string | null = null;

function remember(videos: TikTokVideo[]): void {
  for (const video of videos) videosById.set(video.id, video);
  if (waitingForId && videosById.has(waitingForId)) {
    const id = waitingForId;
    waitingForId = null;
    void report(id);
  }
}

window.addEventListener("message", (event) => {
  if (
    event.source !== window ||
    event.data?.source !== PAGE_HOOK_SOURCE ||
    !Array.isArray(event.data.videos)
  ) {
    return;
  }
  remember(event.data.videos);
});

document.addEventListener("DOMContentLoaded", () => {
  const embedded = document.getElementById(EMBEDDED_DATA_ELEMENT_ID);
  if (!embedded?.textContent) return;
  try {
    remember(extractVideos(JSON.parse(embedded.textContent)));
  } catch {
    console.warn(`${LOG_PREFIX} Couldn't read TikTok's page data.`);
  }
});

// "play" doesn't bubble, so listen in the capture phase to hear every video.
document.addEventListener(
  "play",
  (event) => {
    if (!(event.target instanceof HTMLVideoElement)) return;
    const id = videoIdFrom(ancestorIds(event.target), location.pathname);
    if (!id || reported.has(id)) return;
    if (videosById.has(id)) {
      void report(id);
      return;
    }
    waitingForId = id;
    setTimeout(() => {
      if (waitingForId !== id) return;
      waitingForId = null;
      console.warn(
        `${LOG_PREFIX} Video ${id} is playing, but its TikTok data wasn't captured.`,
      );
    }, DATA_WAIT_MS);
  },
  true,
);

function ancestorIds(element: Element): string[] {
  const ids: string[] = [];
  for (let node = element.parentElement; node; node = node.parentElement) {
    if (node.id) ids.push(node.id);
  }
  return ids;
}

async function report(id: string): Promise<void> {
  const video = videosById.get(id);
  if (!video || reported.has(id)) return;
  reported.add(id);
  const transcript = await loadTranscript(video);

  const { labeled, description } = video.aiLabel;
  console.group(`${LOG_PREFIX} @${video.author} · video ${video.id}`);
  console.log(
    "TikTok AI label:",
    labeled ? `yes${description ? ` ("${description}")` : ""}` : "no",
  );
  console.log("Caption:", video.description || "(none)");
  if (video.onScreenText.length > 0) {
    console.log("On-screen text:", video.onScreenText.join(" | "));
  }
  console.log("Transcript:", transcript);
  console.groupEnd();
}

async function loadTranscript(video: TikTokVideo): Promise<string> {
  const track = pickCaptionTrack(video.captionTracks);
  if (!track) {
    return video.noCaptionReason === null
      ? "none"
      : `none (TikTok reason code ${video.noCaptionReason})`;
  }
  const kind = `${track.autoGenerated ? "auto-generated " : ""}captions, ${track.language || "unknown language"}`;
  try {
    const cues = parseWebVtt(await fetchCaptionFile(track.url));
    return `(${kind}) ${cues.map((cue) => cue.text).join(" ") || "[empty]"}`;
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return `couldn't load ${kind}: ${reason}`;
  }
}

// Try the request the way TikTok's own player would. If the caption server
// refuses requests from the page, the background script fetches it instead.
async function fetchCaptionFile(url: string): Promise<string> {
  try {
    const response = await fetch(url);
    if (response.ok) return await response.text();
  } catch {
    // Blocked by the caption server's cross-origin rules; fall through.
  }
  const request: FetchCaptionRequest = { type: "fetchCaption", url };
  const response: FetchCaptionResponse | undefined =
    await chrome.runtime.sendMessage(request);
  if (!response) throw new Error("the background script didn't answer");
  if (!response.ok) throw new Error(response.error);
  return response.text;
}

// The background service worker fetches caption files for content.ts when the
// caption server refuses requests made from the TikTok page.
import type { FetchCaptionRequest, FetchCaptionResponse } from "./messages.ts";
import { isTikTokCaptionUrl } from "./tiktok.ts";

chrome.runtime.onMessage.addListener(
  (
    message: Partial<FetchCaptionRequest>,
    _sender,
    sendResponse: (response: FetchCaptionResponse) => void,
  ) => {
    if (message.type !== "fetchCaption") return false;
    // The address came from the web page, so only fetch from TikTok's own servers.
    if (typeof message.url !== "string" || !isTikTokCaptionUrl(message.url)) {
      sendResponse({ ok: false, error: "not a TikTok caption address" });
      return false;
    }
    void fetchText(message.url).then(sendResponse);
    return true; // Keeps the channel open until sendResponse is called.
  },
);

async function fetchText(url: string): Promise<FetchCaptionResponse> {
  try {
    const response = await fetch(url, { credentials: "omit" });
    return response.ok
      ? { ok: true, text: await response.text() }
      : { ok: false, error: `the caption server answered ${response.status}` };
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    return { ok: false, error: reason };
  }
}

